#define EPSILON 0.0005
#define MIN_DISTANCE 0.005
#define MAX_DISTANCE 25. 
#define PRECISION 0.001
#define MAX_STEPS 155
#define BALL_RADIUS 5.5
#define SPOT_LIGHT_RADIUS 6.
#define SHAPE_CYCLE 10.
#define BLINK_SPEED 3.
#define REPEAT_PATTERN 10.1
#define TIME_SPEED_FACTOR 1.5
#define PI 3.1415926
#define SPOT_LIGHT_SPEED 0.6

struct Material {
    vec3 ambientColor;
    vec3 diffuseColor;
    vec3 specularColor;
    float alpha;
};



Material greyM() {
  vec3 aCol = vec3(0.1);
  vec3 dCol = vec3(0.1);
  vec3 sCol = vec3(0.1);
  float a = 35.;

  return Material(aCol, dCol, sCol, a);
}


Material grey;

// an array with various 'shapes' of a gyroid
const float ppTable[5] = float[5](
    5.0, 7.0, 6.0, 8., 10.
);


float sdSphere(vec3 pr, vec3 c, float r, mat3 tm) {
    vec3 p = pr * tm;
    float shapesCount = float(ppTable.length());
    int shape2 = int(mod(mod(iTime / SHAPE_CYCLE, shapesCount * SHAPE_CYCLE), shapesCount));
    int shape1 = int(mod((float(shape2 + 1)), shapesCount));
    float distSphere = abs(length(p - c) - r) - 0.2; // abs and (-0.09) at the end is to make a shell instead of a sphere 

    float gyroidDistance;
    float cycleTime = mod(iTime, SHAPE_CYCLE);
    vec3 pp1 = ppTable[shape1] * p; vec3 ve1 = pp1.xxz;
    vec3 pp2 = ppTable[shape2] * p; vec3 ve2 = pp1.zxy;


    if (cycleTime < BLINK_SPEED) {
         ve1 = mix(pp2.xxz, ve1, cycleTime / BLINK_SPEED);   
         ve2 = mix(pp2.zxy, ve2, cycleTime / BLINK_SPEED);   
    }


    gyroidDistance = abs(dot(sin(ve1), cos(ve2)) / 10.) - 0.05;
    return max(distSphere, gyroidDistance);
}

float scene(vec3 p) {
    float zi = mod(p.z + 0.5 * REPEAT_PATTERN, REPEAT_PATTERN) - 0.5 * REPEAT_PATTERN;
    vec3 pr = vec3(p.x + sin(iTime), p.y + cos(iTime * 2.) * 2., zi);
   // return sdSphere(pr, vec3(0., 0., 0.), BALL_RADIUS, rotateZ(iTime / 2.)); 
   return sdSphere(pr, vec3(0., 0., 0.), BALL_RADIUS, rotateZ(iTime + cos(p.z / 2.5 + 1. * cos(iTime)))); 
}



// vector normal to sphere with cener c and radius r
vec3 calcNormal(vec3 p) {
  vec2 e = vec2(1.02, -1.02) * EPSILON;
  return normalize(
    e.xyy * scene(p + e.xyy) +
    e.yyx * scene(p + e.yyx) +
    e.yxy * scene(p + e.yxy) +
    e.xxx * scene(p + e.xxx));
}


struct RaymarchRes {
    vec3 p; // surface hit point
    float d; // distance
};


RaymarchRes raymarch(vec3 ro, vec3 rd) {
    float t = MIN_DISTANCE; 
    RaymarchRes res;
    res.d = MAX_DISTANCE;

    for (int i = 0; i < MAX_STEPS; i++) {
        vec3 p = ro + t * rd;
        float sf = scene(p); 
        t += sf;

        if (sf < PRECISION) { // we hit the surface at point p
            res.p = p;
            res.d = sf;
            break;
        } else if (sf > MAX_DISTANCE) break; // we did not hit anything but are to far away from camera 
            //t += sf.d; // we did not hit anything, keep on trying
    }

    res.d = t;
    return res;
}

mat3 camera(vec3 cameraPos, vec3 lookAtPoint) {
    vec3 cd = normalize(lookAtPoint - cameraPos);
    vec3 cr = normalize(cross(vec3(0, 1, 0), cd));
    vec3 cu = normalize(cross(cd, cr));

    return mat3(-cr, cu, -cd);
}

vec3 calculateCameraPosition(vec3 lookAt, vec2 uv) {
   vec3 ro = vec3(0.4, 0.4, lookAt.z - 4.); 
   return ro;
}

vec3 calculateLightPosition(vec3 lookAt) {
    vec3 lightVector = vec3(0., 0., 0.);
    return lightVector;
}
