vec3 wanderOnSphere(float time, float radius) {
    float azimuth = mod(time * SPOT_LIGHT_SPEED, 2.0 * PI); 
    float elevation = sin(time * SPOT_LIGHT_SPEED * 0.5) * PI * 2.5; 

    // change coordinates to cartesian system
    float x = radius * cos(elevation) * cos(azimuth);
    float y = radius * sin(elevation);
    float z = radius * cos(elevation) * sin(azimuth) + iTime * TIME_SPEED_FACTOR ;

    return vec3(x, y, z);
}


vec3 calculateLight(vec2 fragCoord, RaymarchRes rr, vec3 rd, vec3 lo, vec3 backgroundColor) {
    vec3 po = rr.p;
    vec3 normalToSurfaceVector = calcNormal(po);
    vec3 l = -normalize(-lo + po); // light direction
    Material m = grey;
    float zi = clamp((rr.p.z - iTime * TIME_SPEED_FACTOR + 4.) / REPEAT_PATTERN, 0., 1.); // we are making transition between materials - the further you are the more different color
    zi = exp(-zi*zi*zi*2.);

  //  m = mixMaterials(gold, grey, abs(po.x - po.y)); 
    vec3 color = m.ambientColor; 
    vec3 diffusion = clamp(dot(l, normalToSurfaceVector), 0., 1.) * m.diffuseColor; // diffusion light
    float dotRV = clamp(dot(reflect(l, normalToSurfaceVector), rd), 0., 1.);
    vec3 specular =  clamp(pow(dotRV, m.alpha), 0., 1.) * m.specularColor; // specular light
    color += (specular + diffusion);
    float y2 = sin(iTime * 2.);
    float y1 = 2.;//(sin(iTime) + 1.) / 2.;
    float ys = 0. + sin(iTime) / 2.;


   //float spotSize = 4.5;
    vec3 spotLight1 = vec3(1., 1., 1.);
    vec3 spotLight2 = vec3(1., 1., 1.);
    vec3 spotLight3 = vec3(1., 1., 1.);
  /* 
    if (po.y < y1 + y2 && po.y > y2) {
        color = mix(spotLight1, color, smoothstep(y2, y1 + y2, po.y));
    } else if (po.y > y2 - y1 && po.y < y2) {
        color = mix(color, spotLight1, smoothstep(y2 - y1, y2, po.y));
    }
    */

    float dd = length(wanderOnSphere(iTime, BALL_RADIUS) - po);
    color = +mix(color, color + spotLight1, smoothstep(0., SPOT_LIGHT_RADIUS, SPOT_LIGHT_RADIUS - dd));
    dd = length(wanderOnSphere(iTime + 7., BALL_RADIUS) - po);
    color = +mix(color, color + spotLight2, smoothstep(0., SPOT_LIGHT_RADIUS, SPOT_LIGHT_RADIUS - dd));
    dd = length(wanderOnSphere(iTime + 12., BALL_RADIUS) - po);
    color = +mix(color, color + spotLight3, smoothstep(0., SPOT_LIGHT_RADIUS, SPOT_LIGHT_RADIUS - dd));

    color *= zi;
    color = clamp(color, 0., 1.);


    vec2 q = fragCoord.xy / iResolution.xy;
    color = vec3(color * pow(20. * q.x * q.y * (1.0 - q.x) * (1.0 - q.y), 0.5)); // vigniete

    return color;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    vec2 uv = (fragCoord-.5*iResolution.xy)/iResolution.y;

    grey = greyM();

    vec3 lookAt = vec3(0.0,0.5, iTime * TIME_SPEED_FACTOR);
    vec3 ro = calculateCameraPosition(lookAt, uv);
    vec3 rd = camera(ro, lookAt) * normalize(vec3(uv, -0.1)); // przy -6 fajne wzory
    vec3 lo = calculateLightPosition(lookAt);

    vec4 backgroundColor = vec4(mix(vec3(0., 0.01, .1), vec3(0., 0., 0.), uv.y) * 1.8, 1.0);
    RaymarchRes rr = raymarch(ro, rd);

    fragColor = (rr.d < MAX_DISTANCE) ? vec4(calculateLight(fragCoord, rr, rd, lo, backgroundColor.xyz), 1.0) : backgroundColor;    
}

mat3 rotateX(float theta) {
    float c = cos(theta);
    float s = sin(theta);
    return mat3(
        vec3(1, 0, 0),
        vec3(0, c, -s),
        vec3(0, s, c)
    );
}

mat3 rotateY(float theta) {
    float c = cos(theta);
    float s = sin(theta);
    return mat3(
        vec3(c, 0, s),
        vec3(0, 1, 0),
        vec3(-s, 0, c)
    );
}

mat3 rotateZ(float theta) {
    float c = cos(theta);
    float s = sin(theta);
    return mat3(
        vec3(c, -s, 0),
        vec3(s, c, 0),
        vec3(0, 0, 1)
    );
}
mat3 identity() {
    return mat3(
        vec3(1, 0, 0),
        vec3(0, 1, 0),
        vec3(0, 0, 1)
    );
}
